<?php
defined('ABSPATH') || exit;
function fin_review_stars($rating) {
    $percentage = max(0, min(100, (float)$rating * 20));
    return '<span class="fin-review-stars" aria-hidden="true"><span>★★★★★</span><span class="fin-review-fill" style="width:' . esc_attr($percentage) . '%">★★★★★</span></span>';
}
function fin_home_reviews() {
    // Only approved comments on currently published products contribute to the score.
    $reviews = get_comments(['status'=>'approve','post_type'=>'product','number'=>0,'orderby'=>'comment_date_gmt','order'=>'DESC','meta_query'=>[['key'=>'rating','value'=>[1,5],'compare'=>'BETWEEN','type'=>'NUMERIC']]]);
    $reviews = array_values(array_filter($reviews, fn($r) => get_post_status($r->comment_post_ID)==='publish' && (float)get_comment_meta($r->comment_ID,'rating',true)>=1 && (float)get_comment_meta($r->comment_ID,'rating',true)<=5));
    $count=count($reviews); $average=$count?array_sum(array_map(fn($r)=>(float)get_comment_meta($r->comment_ID,'rating',true),$reviews))/$count:0;
    // Fictional social proof is excluded from the storefront, including legacy settings.
    if (!$count) return;
    ?><section id="fin-customer-reviews" class="container fin-customer-reviews" aria-labelledby="fin-reviews-title"><div class="section-heading"><div><h2 id="fin-reviews-title">Your experience, in your words.</h2><p>Product ratings and feedback shared by our customers.</p></div><a class="text-link" href="<?php echo esc_url(fin_shop_url()); ?>">Choose a product to review ↗</a></div><div class="fin-review-overview"><div class="fin-review-score"><strong><?php echo $count ? esc_html(number_format($average,1,'.','')) : '—'; ?></strong><span>/ 5</span></div><div><?php echo fin_review_stars($average); ?><p><?php echo $count ? esc_html($count . ($count===1?' approved review':' approved reviews')) : 'No ratings yet'; ?></p></div></div><?php if ($count) : ?><div class="fin-feedback-grid"><?php foreach(array_slice($reviews,0,6) as $review) : $rating=(float)get_comment_meta($review->comment_ID,'rating',true); ?><article class="fin-feedback-card"><div class="fin-feedback-rating"><?php echo fin_review_stars($rating); ?><span><?php echo esc_html(number_format($rating,1,'.','')); ?>/5</span></div><blockquote><?php echo esc_html(wp_trim_words(wp_strip_all_tags($review->comment_content),65)); ?></blockquote><div class="fin-feedback-person"><strong><?php echo esc_html($review->comment_author); ?></strong><?php if(function_exists('wc_review_is_from_verified_owner') && wc_review_is_from_verified_owner($review->comment_ID)) : ?><span>Verified owner</span><?php endif; ?><time datetime="<?php echo esc_attr(get_comment_date('c',$review)); ?>"><?php echo esc_html(get_comment_date('M j, Y',$review)); ?></time></div><a href="<?php echo esc_url(get_permalink($review->comment_post_ID).'#reviews'); ?>"><?php echo esc_html(get_the_title($review->comment_post_ID)); ?> ↗</a></article><?php endforeach; ?></div><?php else : ?><div class="fin-feedback-empty"><h3>Be the first to share your thoughts.</h3><p>Open a product and use its Reviews tab to leave a rating and feedback. Reviews appear here after approval.</p></div><?php endif; ?></section><?php
}

