ng'],1,'.','')); ?> / 5</strong><span>Sample rating</span></div><h4><?php echo esc_html($sample['title']); ?></h4><p><?php echo esc_html($sample['body']); ?></p><footer><span>♡ <?php echo (int)$sample['likes']; ?> found this helpful <small>· demo count</small></span><span>Fictional feedback</span></footer></div></article><?php endforeach; ?></div><div class="fin-review-carousel-controls"><button type="button" data-review-prev aria-label="Previous feedback">←</button><div class="fin-review-dots" role="group" aria-label="Choose a feedback card"><?php foreach($samples as $i=>$sample):?><button type="button" data-review-index="<?php echo (int)$i; ?>" aria-label="Show feedback <?php echo (int)$i+1; ?>"><?php echo (int)$i+1; ?></button><?php endforeach; ?></div><button type="button" data-review-next aria-label="Next feedback">→</button></div><p class="fin-review-position" data-review-position aria-live="polite"></p></div></section><?php
