add_action('customize_register',function($c){$c->add_section('fin_demo_feedback_section',['title'=>'FINNORA — Demo feedback','priority'=>170]);$c->add_setting('fin_demo_feedback',['default'=>true,'sanitize_callback'=>fn($v)=>(bool)$v]);$c->add_control('fin_demo_feedback',['label'=>'Show clearly labelled fictional feedback posts','description'=>'Preview content only; turn off before collecting real customer feedback.','section'=>'fin_demo_feedback_section','type'=>'checkbox']);});
add_action('wp_enqueue_scripts',function(){wp_enqueue_style('fin-feedback-feed',get_template_directory_uri().'/assets/feedback-feed.css',['fin-breathing-room'],filemtime(get_template_directory().'/assets/feedback-feed.css'));},55);

add_action('wp_enqueue_scripts',function(){if(is_front_page())wp_enqueue_script('fin-review-carousel',get_template_directory_uri().'/assets/review-carousel.js',[],filemtime(get_template_directory().'/assets/review-carousel.js'),true);},60);
